{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://example.com/beta-cruiser-config.schema.json",
  "title": "beta cruiser configuration schema",
  "description": "schema defining valid configuration data for pre-production beta test cruisers used in maritime and space trial programs",
  "type": "object",
  "required": ["cruiser_serial", "beta_test_cohort", "hull_specs", "active_test_modules", "trial_objectives"],
  "properties": {
    "cruiser_serial": {
      "type": "string",
      "description": "unique alphanumeric identifier for the beta cruiser, prefixed with the assigned [beta_fleet_registry_code] to distinguish test units from active service vessels",
      "pattern": "^[a-z0-9]{2,4}-[0-9]{3,6}$"
    },
    "beta_test_cohort": {
      "type": "string",
      "description": "test group assigned to the cruiser for structured beta evaluation",
      "enum": ["cohort_alpha", "cohort_bravo", "cohort_charlie", "cohort_delta"]
    },
    "hull_specs": {
      "type": "object",
      "description": "core physical specifications for the cruiser's structural components",
      "required": ["displacement_tonnes", "hull_material", "max_operating_depth_meters", "propulsion_type"],
      "properties": {
        "displacement_tonnes": {
          "type": "number",
          "minimum": 1200,
          "maximum": 4500
        },
        "hull_material": {
          "type": "string",
          "enum": ["reinforced_carbon_composite", "titanium_alloy", "ablative_ceramic_mesh", "radiation_shielded_alloy"]
        },
        "max_operating_depth_meters": {
          "type": "integer",
          "minimum": 150,
          "maximum": 1200
        },
        "propulsion_type": {
          "type": "string",
          "enum": ["diesel_electric", "compact_nuclear", "hydrogen_fuel_cell", "plasma_thruster"]
        }
      },
      "additionalProperties": false
    },
    "active_test_modules": {
      "type": "array",
      "description": "list of beta test software and hardware modules installed on the cruiser for trial evaluation",
      "items": {
        "type": "object",
        "required": ["module_id", "module_function", "beta_firmware_version"],
        "properties": {
          "module_id": {
            "type": "string",
            "pattern": "^mod-[a-z0-9_]+-\\d{4}$"
          },
          "module_function": {
            "type": "string",
            "enum": ["navigation", "targeting", "long_range_communications", "life_support", "stealth", "passive_sensor", "active_sensor", "countermeasures"]
          },
          "beta_firmware_version": {
            "type": "string",
            "pattern": "^\\d+\\.\\d+\\.beta\\.\\d+$"
          }
        },
        "additionalProperties": false
      },
      "minItems": 3,
      "maxItems": 15
    },
    "trial_objectives": {
      "type": "array",
      "description": "list of structured test goals the cruiser is assigned to complete during the beta trial period",
      "items": {
        "type": "string",
        "minLength": 10
      },
      "minItems": 1
    },
    "custom_trial_modifications": {
      "type": "object",
      "description": "optional custom adjustments to cruiser systems, which must be pre-approved by [beta_test_oversight_board] prior to deployment",
      "patternProperties": {
        "^[a-z0-9_]{3,20}$": {
          "type": ["string", "number", "boolean"]
        }
      },
      "additionalProperties": false
    }
  },
  "additionalProperties": false
}
